\label{thm:onbexplicit}
Let $K\ge2${, and} put $k=K-1$. Let $a\ge1$, and let $\alpha = [a_0; a_1, a_2, \ldots]$ be an
irrational number with $a_i \leq a$ for all $i \geq 1$. 
For each $N\ge1$, with $\operatorname{lcm}_k\mid N$, let $U_N$ be the map given by Proposition \ref{prop:UNmap}.
Then:
\begin{enumerate}
\item Let $D_N = {\rm diag}(\frac{1}{N/k+1}, \frac{1}{N/(k-1)+1},\ldots, \frac{1}{N+1})$ and define for each $l \in \mathscr{B}_N$
  \begin{equation}
  \varphi_{l}(z):=
  \sum_{\substack{j\in\mathbb Z_{\ge0}^K\\j_1+\cdots+j_K=N}}
  \binom Nj^{1/2}z^j
  e\left(\alpha\sum_{s=1}^Kj_s^2
  +U_N(j_1,\ldots,j_k)\cdot D_N l\right),
  \label{eq:originalBasis}
  \end{equation}
 where
  $\binom Nj=N!/(j_1!\cdots j_K!)$.
  Then $\{\varphi_{l}:l\in\mathscr{B}_N\}$ is an orthonormal basis
  of $\mathrm{H}_N${.}
\item Assuming the estimate in Theorem~\ref{thm:box},
  \[
  \sup_{\substack{N\ge1\\ \operatorname{lcm}_k\mid N}}
  \ \sup_{l\in\mathscr{B}_N}
  \|\varphi_{l}\|_{L^\infty(\mathbb{S}^{2K-1})}\ll_{K,a}1{.}
  \]
\item The divisibility condition can be
  removed: assuming Theorem~\ref{thm:box}, then, for every $N\ge0$, the space $\mathrm{H}_N$ admits an orthonormal basis
  $(\psi_\nu)_{1\leq \nu\le\dim\mathrm{H}_N}$ satisfying
  \[
    \sup_{1\leq \nu\le\dim\mathrm{H}_N}
    \|\psi_\nu\|_{L^\infty(\mathbb{S}^{2K-1})}\ll_{K,a}1.
  \]
\end{enumerate}

\label{lem:poisson1d}
We have, for all $n \in \mathbb{Z}$,
\begin{align}
q_\lambda(n)\ll H_\lambda^{-1/2}e^{-\rho_\lambda(n)/4} \quad \text{and} \quad
|\Delta q_\lambda(n)|\ll H_\lambda^{-3/2}e^{-\rho_\lambda(n)/4}.
\label{eq:poissonPointwiseBound}
\end{align}

Stirling's inequalities give
\begin{equation} \label{eq:lemma_first}
q_\lambda(n)^2\ll(1+n)^{-1/2}e^{-F_\lambda(n)},
\end{equation}
where $F_\lambda(n):=n\log(n/\lambda)-n+\lambda= {\int_{\lambda}^n (n-t)\frac{\mathrm{d} t}{t}}$. Separating into cases, $n\geq \lambda \geq 0$ and $\lambda > n\geq 0$, we can bound the integral from below by
\begin{equation} \label{eq:lemma_second}
F_\lambda(n)\ge\frac{(n-\lambda)^2}{2(\lambda+|n-\lambda|)}
\ge\frac{\rho_\lambda(n)^2}{2(1+\rho_\lambda(n))}\ge\frac{\rho_\lambda(n)-1}{2}.
\end{equation}
The elementary inequality $\frac{1}{a} \leq \frac{1}{b} + |\frac{a^2}{b^2}-1|$, for $a,b\geq 1$, applied to $a=(n+1)^{1/2}$ and $b=H_\lambda$ implies
\begin{equation} \label{eq:lemma_bound_ineq}
(1+n)^{-1/2}\le H_\lambda^{-1}(1+\rho_\lambda(n))
\ll H_\lambda^{-1}e^{\rho_\lambda(n)/4}.
\end{equation}
To bound $\Delta q_{\lambda}$ we note that for $n \geq 0$ 
\[
\Delta q_\lambda(n)
=q_\lambda(n)\frac{\lambda-n-1}
{\sqrt{n+1}(\sqrt\lambda+\sqrt{n+1})}.
\]
Since $\sqrt\lambda+\sqrt{n+1}\ge H_\lambda$, the quotient satisfies
\[
\left|\frac{\lambda-n-1}
{\sqrt{n+1}(\sqrt\lambda+\sqrt{n+1})}\right|
\le\frac{1+\rho_\lambda(n)}{\sqrt{n+1}}
\le\frac{(1+\rho_\lambda(n))^2}{H_\lambda},
\]
where in the last inequality we reused the first inequality in \eqref{eq:lemma_bound_ineq}. Combining this with \eqref{eq:lemma_first} and \eqref{eq:lemma_second}, we get 
$$
| \Delta q_{\lambda}(n) | \ll H_{\lambda}^{-3/2} (1 + \rho_{\lambda}(n))^{5/2} e^{-\rho_{\lambda}(n) / 2} \ll H_{\lambda}^{-3/2} e^{-\rho_{\lambda}(n) / 4}.
$$
Also $|\Delta q_{\lambda}(-1)| = e^{-\lambda / 2}$ and $|\Delta q_{\lambda}(- n)| = 0$ for $n > 1$. Therefore the above inequality also holds for negative $n$.

\label{lem:fouriermass}
For $m\in\mathbb{Z}$ put
\begin{align}
q_{\lambda,m}(n):=q_\lambda(n)\eta(n/H_{\lambda}-m).
\label{eq:localizedMultinomialSequence}
\end{align}
Then $q_\lambda=\sum_mq_{\lambda,m}$, each $q_{\lambda,m}$ is
supported on $\{n:\ |n/H_\lambda-m|<1\}$ and
\begin{align}
\sum_{m\in\mathbb{Z}}\int_0^1|\widehat{q_{\lambda,m}}(u)|\,\mathrm{d} u\ \ll\ H_\lambda^{-1/2},
\label{eq:multinomialTotalFourierMass}
\end{align}
where the implied constant {is} independent of $\lambda >0$.

\label{def:shiftedbasis}
Let $N\geq 0$ and set
\begin{align}
b:=N-\operatorname{lcm}_k\Bigl\lfloor\frac N{\operatorname{lcm}_k}\Bigr\rfloor \quad \text{and} \quad N'=N-b.
\end{align}
Also write
\begin{align}
D:=\binom{N+k}{k}=\dim\mathrm{H}_N\quad \text{and}\quad
D':=\binom{N'+k}{k}=\dim\mathrm{H}_{N'}.
\label{eq:dimensions}
\end{align}
For $l\in\mathscr{B}_{N'}$ put
\begin{align}
\varphi^b_{l}(z)
=\Bigl(\frac{D}{D'}\Bigr)^{1/2}
\sum_{\substack{n\in\mathbb{Z}_{\ge0}^K,\\ n_1+\cdots+n_K=N\\ n_K\ge b}}
\binom Nn^{1/2}z^n\,
e\Bigl(\alpha\sum_{s=1}^Kn_s^2
+U_{N'}(n_1,\ldots,n_k)\cdot D_{N'}l\Bigr).
\label{eq:shiftedBasis}
\end{align}

By \eqref{def:innerprod} we have
\begin{align*}
\langle\varphi^b_{l},\varphi^b_{l'}\rangle
=\frac1{D'}
\sum_{x\in\mathscr{S}_{N'}}
e\bigl(U_{N'}(x)\cdot D_{N'}(l-l')\bigr)
& =\frac1{D'}\sum_{w\in\mathscr{B}_{N'}}
e\bigl(w\cdot D_{N'}(l-l')\bigr) \\
& = \prod_{s=1}^k \Biggl(  \frac{1}{{N'}/s+1}\sum_{v=0}^{{N'}/s} e\left(\frac{v (l_{k+1-s}-l'_{k+1-s})}{{N'}/s+1} \right)\Biggr)
\\ & =\delta_{l,l'}.
\end{align*}
Since the stated span has dimension $D'=\# \mathscr{B}_{N'}$, the proposition follows.

{
We can assume $N\geq1$. {By continuity we may also assume $r_s>0$ for every $s$.}
First note that
\[
\frac{D}{D'}=\prod_{s=1}^k\left(1+\frac{b}{N'+s}\right)
\leq\prod_{s=1}^k\left(1+\frac{\operatorname{lcm}_k}{s}\right)\ll_K1.
\]
By Proposition \ref{prop:UNmap}, there are
finite sets $L_i\subset\mathbb{Z}^k\times\mathbb{Z}$ and affine maps
$A_ix+a_i\in\text{Aff}_k(\mathbb{Z})$, for $1\leq i\leq n_0$, such that
\[
\mathscr{S}_{N'}=\bigsqcup_{i=1}^{n_0}\mathscr{P}(L_i) \quad \text{and} \quad
U_{N'}(x)=A_ix+a_i\quad \text{for} \quad x\in\mathscr{P}(L_i),
\]
where $n_0\ll_K1$, $\#L_i\ll_K1$ and $|v|_1\ll_K1$ for every $(v,d)\in L_i$. Let $\pi : \mathbb{Z}^k \rightarrow \mathbb{Z}^K$ be defined by $\pi((v_1, \ldots, v_k)) = (v_1, \ldots, v_k, 0)$.
Define the lifted set $L_i'=\{(\pi(v),d) : (v,d)\in L_i\}\cup {\{({\bf 1},-N),(-{\bf 1},N)\}}$, where ${\bf 1} = (1,\ldots, 1)\in {\mathbb{Z}^K}$ so that
\begin{align*}
\{ n \in \mathbb{Z}^K : n_1+\cdots+n_K=N,\ n_K\ge b\}
 & = \{ n \in \mathbb{Z}^K : (n_1,{\ldots},n_k)\in\mathscr{S}_{N'},\ n_1+\cdots+n_K=N\} \\
 & = \bigsqcup_{i=1}^{n_0}\mathscr{P}(L_i').
\end{align*}
Therefore,
\begin{align}
\varphi^b_{l}(z)=\Bigl(\frac D{D'}\Bigr)^{1/2}
\sum_{i=1}^{n_0}e\bigl(a_i\cdot D_{N'}l\bigr)
\sum_{{n\in\mathscr{P}(L_i')}}
a_{N,r}(n)\,e\Bigl(\alpha\sum_{s=1}^Kn_s^2+\xi_i\cdot n\Bigr),
\label{eq:basisSplitIntoPieces}
\end{align}
where $\xi_i:=\theta+\pi(A_i^{\mathsf T}D_{N'}l)\in\mathbb{R}^K$. By \eqref{eq:poissonFactorizationMultinomial} we have
$a_{N,r}(n)=c_N\prod_{s=1}^Kq_{Nr_s}(n_s)$
{for $n\in\mathscr{P}(L_i')$}. Fourier inversion then gives
\[
a_{N,r}(n)=\sum_{m\in \mathbb{Z}^K} c_N  \int_{[0,1]^K}\prod_{s=1}^K \widehat{q_{Nr_s,m_s}}(u_s) e(n\cdot u) \mathrm{d} u,
\]
where $u=(u_1,\ldots,u_K)$. Since $\prod_{s=1}^K {q_{Nr_s,m_s}}(n_s)$ is supported in the box $J_m=\{n\in \mathbb{Z}^K : |n_s/H_s-m_s| \leq 1\ {\text{for }1\le s\le K}\}$, for $m\in \mathbb{Z}^K$, we commute the sums in \eqref{eq:basisSplitIntoPieces} {to obtain}
\begin{align}
|\varphi^b_{l}(z)|\ll_K c_N\sum_{i=1}^{n_0}\sum_{m\in\mathbb{Z}^K}
\int_{[0,1]^K}\prod_{s=1}^K|\widehat{q_{Nr_s,m_s}}(u_s)|\,
\Bigl|\sum_{n\in \mathscr{P}(L_i') \cap J_m}
e\Bigl(\alpha\sum_{s=1}^Kn_s^2+(\xi_i+u)\cdot n\Bigr)\Bigr|\,\mathrm{d} u.
\end{align}
The sectional bound of Theorem \ref{thm:box} then applies in dimension $K$,
with all $c_j=1$ and $w_0=\mathbf1$, producing
\begin{align}
\Bigl|\sum_{n\in \mathscr{P}(L_i') \cap J_m}
e\Bigl(\alpha\sum_{s=1}^Kn_s^2+(\xi_i+u)\cdot n\Bigr)\Bigr|
\ll_{K,a}\operatorname{sect}(\mathbf1;J_m)^{1/2}
\leq\Bigl(\prod_{s\ne q}\#J_{m,s}\Bigr)^{1/2}
\ll_K\prod_{s\ne q}H_s^{1/2},
\label{eq:sectionalVolumeOfTile}
\end{align}
because $\operatorname{len}(\mathbf1;J_m)\geq\#J_{m,q}$. Here $H_q=\max_{1\leq s\leq K} H_s \asymp_K (1+N)^{1/2}$. 
We deduce
\begin{align*}
|\varphi^b_{l}(z)|
&\ll_{K,a}c_N\prod_{s\ne q}H_s^{1/2}
\prod_{s=1}^K\Bigl(\sum_{m_s\in\mathbb{Z}}\int_0^1
|\widehat{q_{Nr_s,m_s}}(u_s)|\,\mathrm{d} u_s\Bigr)\\
&\ll_{K,a}c_N\prod_{s\ne q}H_s^{1/2}\prod_{s=1}^KH_s^{-1/2}
=c_NH_q^{-1/2}\ll_K1,
\end{align*}
where we used Lemma \ref{lem:fouriermass} and that $c_N \asymp_K {N^{1/4}}$.
This finishes the proof.
